<?php
require_once 'config.php'; require_login();
$id=(int)($_GET['id']??0);$q=$pdo->prepare('SELECT st.*,se.title semester_title FROM students st JOIN semesters se ON se.id=st.semester_id WHERE st.id=?');$q->execute([$id]);$student=$q->fetch();
if(!$student){http_response_code(404);exit('Student not found.');}
$pageTitle='Student profile';
$q=$pdo->prepare("SELECT su.subject_code,su.subject_name,COUNT(a.id) total,SUM(a.status='present') present_count,SUM(a.status='absent') absent_count FROM subjects su LEFT JOIN attendance a ON a.subject_id=su.id AND a.student_id=? WHERE su.semester_id=? GROUP BY su.id ORDER BY su.subject_code");$q->execute([$id,$student['semester_id']]);$summary=$q->fetchAll();
$q=$pdo->prepare("SELECT a.attendance_date,a.status,su.subject_code,su.subject_name FROM attendance a JOIN subjects su ON su.id=a.subject_id WHERE a.student_id=? ORDER BY a.attendance_date DESC LIMIT 250");$q->execute([$id]);$history=$q->fetchAll();
require 'partials/header.php';
?>
<div class="section-heading"><div><h2>Student profile</h2><p>Subject-wise attendance and saved class history.</p></div><a class="btn secondary" href="students.php">← Students</a></div>
<section class="panel profile-hero"><span class="profile-avatar"><?= e(strtoupper(substr($student['student_name'],0,1))) ?></span><div class="profile-main"><span class="eyebrow">STUDENT RECORD</span><h2><?= e($student['student_name']) ?></h2><p><?= e($student['semester_title']) ?> · Roll <?= e($student['roll_no']) ?></p></div><div class="profile-meta"><span>Registration</span><b><?= e($student['registration_no']??'—') ?></b><span>Session</span><b><?= e($student['session_name']??'—') ?></b><span>Phone</span><b><?= e($student['phone']??'—') ?></b></div></section>
<section class="panel subject-panel"><div class="panel-heading"><div><h3>Subject-wise summary</h3><p>Percentages use the saved attendance records.</p></div></div><div class="table-wrap"><table><thead><tr><th>Subject</th><th>Total</th><th>Present</th><th>Absent</th><th>Rate</th></tr></thead><tbody><?php foreach($summary as $r):$t=(int)$r['total'];$pr=(int)($r['present_count']??0);$ab=(int)($r['absent_count']??0);$pc=$t?round($pr/$t*100):0; ?><tr><td><b><?= e($r['subject_code']) ?></b><small class="cell-sub"><?= e($r['subject_name']) ?></small></td><td><?= $t ?></td><td><span class="pill present"><?= $pr ?></span></td><td><span class="pill absent"><?= $ab ?></span></td><td><?= $t?$pc.'%':'—' ?></td></tr><?php endforeach; ?></tbody></table></div></section>
<section class="panel subject-panel"><div class="panel-heading"><div><h3>Attendance history</h3><p>Latest saved records for this student.</p></div><a class="text-link" href="export.php?student_id=<?= $id ?>">Export CSV ↓</a></div><div class="table-wrap"><table><thead><tr><th>Date</th><th>Subject</th><th>Status</th></tr></thead><tbody><?php foreach($history as $r): ?><tr><td><?= e(date('d M Y',strtotime($r['attendance_date']))) ?></td><td><b><?= e($r['subject_code']) ?></b><small class="cell-sub"><?= e($r['subject_name']) ?></small></td><td><span class="pill <?= $r['status']==='present'?'present':'absent' ?>"><?= e(ucfirst($r['status'])) ?></span></td></tr><?php endforeach; ?></tbody></table></div><?php if(!$history): ?><div class="empty-state"><b>No attendance history yet</b><p>Saved class records will appear here.</p></div><?php endif; ?></section>
<?php require 'partials/footer.php'; ?>
